using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Services;[Authorize]public sealed class DetailsModel(OrcaFacilDbContext db,ICurrentAccountService account):PageModel{public ServiceCatalogItem Item{get;private set;}=null!;public List<ServicePriceHistory> History{get;private set;}=[];public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct){if(account.AccountId is not Guid accountId)return Forbid();var item=await db.ServiceCatalogItems.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.AccountId==accountId&&!x.IsDeleted,ct);if(item is null)return NotFound();Item=item;History=await db.ServicePriceHistories.AsNoTracking().Where(x=>x.AccountId==accountId&&x.ServiceCatalogItemId==id&&!x.IsDeleted).OrderByDescending(x=>x.ChangedAt).ToListAsync(ct);return Page();}}
